arguments.new_string:
# Weekly revenue & costs from ledger (last 7 days)
if DAY > 0:
    r = nm.query(f"SELECT category, SUM(amount) as amt FROM ledger WHERE day > {DAY-7} GROUP BY category")
    for x in r['rows']:
        row[f"wk_{x['category']}"] = round(x['amt'], 0)

# Weekly leads & conversions by group (for price/channel experiments)
if DAY > 0:
    r = nm.query(f"""SELECT c.group_id, s.status, COUNT(*) as n FROM subscriptions s
      JOIN customers c ON s.customer_id=c.customer_id
      WHERE s.start_day > {DAY-7} GROUP BY c.group_id, s.status""")
    conv = {}
    for x in r['rows']:
        d = conv.setdefault(x['group_id'], {})
        d[x['status']] = x['n']
    row['wk_leads_conv'] = json.dumps(conv)

