arguments.command:
./novamind-operation python-c "
import novamind_api as nm
# daily sub revenue wk18 + new subs per day
r = nm.query(\"SELECT day, SUM(amount) rev FROM ledger WHERE category='subscription_payment' AND day>=113 GROUP BY day ORDER BY day\")
print('daily sub rev:'); 
for row in r['rows']: print(row['day'], round(row['rev']))
print('--- new subs per day ---')
r = nm.query(\"SELECT start_day, COUNT(*) n, AVG(effective_price) ep FROM subscriptions WHERE start_day>=113 AND status IN ('subscribed','cancelled') GROUP BY start_day ORDER BY start_day\")
for row in r['rows']: print(row['start_day'], row['n'], round(row['ep'],1))
"

