import novamind_api as nm

for g in ['S2','D_S06','D_S07','D_S04','E2']:
    try:
        r = nm.market.get_group_insights(group_id=g)
        print(f"\n===== {g} =====")
        print(r)
    except Exception as e:
        print(g, "ERR", e)

print("\n\n===== SOCIAL POSTS (last 7d, negative-ish) =====")
posts = nm.analytics.get_social_posts(days=7, limit=40)
for p in posts:
    txt = p.get('text','') if isinstance(p,dict) else str(p)
    print(f"  [{p.get('group_id','?') if isinstance(p,dict) else '?'}] {txt[:160]}")

import novamind_api as nm
posts = nm.analytics.get_social_posts(days=7, limit=60)
print(type(posts))
if isinstance(posts, dict):
    print("keys:", list(posts.keys()))
    plist = posts.get('posts', [])
    print("total:", posts.get('total'))
else:
    plist = posts
print("n posts:", len(plist))
for p in plist[:50]:
    if isinstance(p, dict):
        print(f"  day{p.get('day','?')} [{p.get('group_id','?')}] {str(p.get('text',''))[:170]}")
    else:
        print("  ", str(p)[:170])

