try:
    r = nm.enterprise.send_enterprise_deal(deals=deals)
    print("DEALS:", r)
except Exception as e:
    print("DEAL ERROR:", e)

# 2. Ads: turn ON D_S06 ($12K/d content) + D_S05 test ($3K/d content); keep S2 as-is
