    r = nm.marketing.set_targeted_ad_spend(targeted_spend={
        "content_marketing": {"S2": 22000, "D_S06": 12000, "D_S05": 3000},
        "social_media": {"S2": 400},
        "referral_program": {"S2": 400},
    })
    print("ADS:", r)
except Exception as e:
    print("ADS ERROR:", e)

# 3. Lead promos: full dict + D_S05 $20
try:
    r = nm.marketing.set_lead_promotion(by_group={
        "S2": 10, "D_S07": 25, "D_S04": 20, "E2": 40,
        "D_E08": 20, "D_E02": 15, "D_E09": 15, "D_S06": 20, "D_S05": 20,
    })
    print("LEAD PROMOS:", r)
except Exception as e:
    print("LEAD PROMO ERROR:", e)

# 4. research_market x2 ($50K total)
for i in range(2):
    try:
        r = nm.market.research_market()
        print(f"RESEARCH {i+1}:", r)
    except Exception as e:
        print(f"RESEARCH {i+1} ERROR:", e)

