    results['ent_deal'] = r
except Exception as e:
    results['ent_deal'] = f"ERR {e}"

# 3. SOCIAL: support + quality update (max 280 chars)
msg = ("Update: every support ticket is now resolved within 24h - we tripled ops staffing. "
       "Two major quality upgrades ship this month. Thanks for sticking with us as we scale!")
